import os

all_data = []
polymorph_dir = "polymorph_data"

# Get all JSON files
for filename in os.listdir(polymorph_dir):
    if filename.endswith("_polymorphs.json"):
        filepath = os.path.join(polymorph_dir, filename)
        try:
            with open(filepath, 'r') as f:
                data = json.load(f)
                if isinstance(data, list):
                    all_data.extend(data)
        except Exception as e:
            print(f"Error with {filename}: {e}")

# Save consolidated
with open("consolidated_sulphides.json", 'w') as f:
    json.dump(all_data, f)

print(f"Total polymorphs: {len(all_data)}")
